#!/usr/bin/env bash
#
# 10-install-server.sh - bootstrap the FIRST control-plane node with K3s.
#
# This installs K3s as a server with the embedded etcd datastore using
# `--cluster-init`, so this node becomes the initial etcd member and the
# bootstrap cluster. Additional control-plane nodes should then be joined
# with 11-install-server-join.sh until you have three servers (HA quorum).
#
# Idempotent: re-running detects an existing install and exits unless
# --force is given. A node-token is generated by K3s itself and is never
# printed by this script; use 30-token-helper.sh to read it with sudo.
#
# Usage:
#   sudo ./bootstrap/10-install-server.sh [options]
#
# Options:
#   --tls-san <value>       Extra TLS SAN (repeatable). Add every API VIP and
#                           load-balancer DNS name clients will use.
#   --node-ip <ip>          Pin the node IP instead of auto-detecting.
#   --k3s-version <ver>     e.g. v1.29.6+k3s1. Defaults to K3s "stable".
#   --disable <component>   Repeatable; defaults to traefik,servicelb.
#   --write-kubeconfig-mode <mode>  Default 600.
#   --dry-run               Print the install command and exit.
#   --force                 Re-run the installer even if K3s is present.
#
set -euo pipefail

SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SELF_DIR}/.." && pwd)"

K3S_VERSION="${K3S_VERSION:-}"
NODE_IP="${NODE_IP:-}"
KUBECONFIG_MODE="${KUBECONFIG_MODE:-600}"
TLS_SANS=()
DISABLE_LIST=("traefik" "servicelb")
DRY_RUN=0
FORCE=0

while [ $# -gt 0 ]; do
  case "$1" in
    --tls-san) TLS_SANS+=("$2"); shift 2 ;;
    --tls-san=*) TLS_SANS+=("${1#*=}"); shift ;;
    --node-ip) NODE_IP="$2"; shift 2 ;;
    --node-ip=*) NODE_IP="${1#*=}"; shift ;;
    --k3s-version) K3S_VERSION="$2"; shift 2 ;;
    --k3s-version=*) K3S_VERSION="${1#*=}"; shift ;;
    --disable) DISABLE_LIST+=("$2"); shift 2 ;;
    --disable=*) DISABLE_LIST+=("${1#*=}"); shift ;;
    --write-kubeconfig-mode) KUBECONFIG_MODE="$2"; shift 2 ;;
    --write-kubeconfig-mode=*) KUBECONFIG_MODE="${1#*=}"; shift ;;
    --dry-run) DRY_RUN=1; shift ;;
    --force) FORCE=1; shift ;;
    --help|-h) sed -n '2,30p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) printf 'unknown option: %s\n' "$1" >&2; exit 2 ;;
  esac
done

log() { printf '[10-install-server] %s\n' "$*"; }
die() { printf '[10-install-server] ERROR: %s\n' "$*" >&2; exit 1; }

require_root() {
  if [ "$(id -u)" -ne 0 ]; then
    die "must run as root (use sudo)"
  fi
}

if [ ! -f /etc/os-release ]; then
  log "warning: /etc/os-release missing; continuing anyway"
fi

require_root

if command -v k3s >/dev/null 2>&1 || [ -f /etc/systemd/system/k3s.service ]; then
  if [ "${FORCE}" -ne 1 ]; then
    log "K3s server already appears installed; nothing to do (use --force to re-run)"
    exit 0
  fi
  log "--force given; re-running the installer over the existing installation"
fi

# Build the install command. The config file (k3s/config.yaml) is applied by
# the installer via the K3S_CONFIG_FILE hook below when it exists; command
# line flags take precedence over the config file, so leave flags minimal.
INSTALL_ARGS=(
  server
  --cluster-init
  --write-kubeconfig-mode "${KUBECONFIG_MODE}"
)

if [ -n "${NODE_IP}" ]; then
  INSTALL_ARGS+=(--node-ip "${NODE_IP}")
fi

for san in "${TLS_SANS[@]:-}"; do
  [ -n "${san}" ] && INSTALL_ARGS+=(--tls-san "${san}")
done

if [ "${#DISABLE_LIST[@]}" -gt 0 ]; then
  DISABLE_CSV="$(printf '%s,' "${DISABLE_LIST[@]}")"
  INSTALL_ARGS+=(--disable "${DISABLE_CSV%,}")
fi

INSTALL_ENV=("INSTALL_K3S_EXEC=${INSTALL_ARGS[*]}")
if [ -n "${K3S_VERSION}" ]; then
  INSTALL_ENV+=("INSTALL_K3S_VERSION=${K3S_VERSION}")
fi

CONFIG_FILE="${REPO_ROOT}/k3s/config.yaml"
if [ -f "${CONFIG_FILE}" ]; then
  INSTALL_ENV+=("K3S_CONFIG_FILE=${CONFIG_FILE}")
  log "using server config file ${CONFIG_FILE}"
fi

log "planned INSTALL_K3S_EXEC: ${INSTALL_ARGS[*]}"

if [ "${DRY_RUN}" -eq 1 ]; then
  log "dry-run: would run the get.k3s.io installer with the arguments above"
  exit 0
fi

log "downloading and running the official K3s installer (https://get.k3s.io)"
if ! curl -sfL https://get.k3s.io -o /tmp/k3s-install.sh; then
  die "could not download the K3s installer; check network access"
fi
chmod +x /tmp/k3s-install.sh

env "${INSTALL_ENV[@]}" sh /tmp/k3s-install.sh

log "waiting for the k3s systemd unit to come up"
systemctl enable --now k3s.service

# A short, bounded wait for the API server socket to answer.
for _ in $(seq 1 60); do
  if [ -f /etc/rancher/k3s/k3s.yaml ]; then
    break
  fi
  sleep 2
done

if [ ! -f /etc/rancher/k3s/k3s.yaml ]; then
  die "kubeconfig /etc/rancher/k3s/k3s.yaml was not written; check: journalctl -u k3s"
fi

log "kubeconfig written to /etc/rancher/k3s/k3s.yaml"
log "copy it for your user with:"
log "  mkdir -p ~/.kube && sudo cp /etc/rancher/k3s/k3s.yaml ~/.kube/config && sudo chown \$USER ~/.kube/config"
log "next: apply systemd drop-ins from systemd/, then join 2 more servers with 11-install-server-join.sh"
log "done"
